def _shape_steps(
    steps: Sequence[Any],
    roster: Sequence[str],
    *,
    product_name: str,
    entity: Optional[str],
    default_actions: Optional[Dict[str, str]],
    fallback_domain: Dict[str, Any],
) -> List[Dict[str, Any]]:
    shaped: List[Dict[str, Any]] = []
    for index, step in enumerate(steps):
        if not isinstance(step, dict):
            shaped.append(step)
            continue
        item = dict(step)
        block = ""
        for key in ("block", "block_id", "name"):
            block = _label(item.get(key))
            if block:
                break
        if not block:
            shaped.append(item)
            continue
        item["id"] = _label(item.get("id"), "step_%d" % index)
        item["block"] = block
        raw = item.get("input")
        payload = raw if isinstance(raw, dict) else fallback_domain
        item["input"] = prepare_block_input(
            block, payload, roster=roster, product_name=product_name,
            entity=entity, default_actions=default_actions,
        )
        resolved = _label(item.get("action")) or default_block_action(block, default_actions)
        if resolved:
            item["action"] = resolved
            params = item.get("params")
            if not isinstance(params, dict):
                params = {}
            params.setdefault("action", resolved)
            item["params"] = params
        shaped.append(item)
    return shaped


